%% RFPS-AI Dataset - Electromagnetic Simulation and Data Extraction
% MATLAB R2023b
% Keysight ADS 2023 Update 2
%
% Executes ADS Momentum simulations and extracts the complete
% four-port scattering matrix for each pixelated RF structure.
%
% Required files:
%   variables.m
%   array.mat
%   ADS Momentum simulation files generated by ael_creator.m

%% 1. Load configuration and geometries

variables;

file_bat_name = 'em_simulation.bat';

data = load('array.mat', 'array');
array = data.array;

if numel(array) ~= number_layouts
    error('The number of geometries does not match number_layouts.');
end

% Scattering parameter names
s_names = cell(1, 16);

idx = 1;
for p = 1:4
    for q = 1:4
        s_names{idx} = sprintf('S%d%d', p, q);
        idx = idx + 1;
    end
end

%% 2. Initialize output variables

% Binary geometry representations
inputs = zeros(number_layouts, (array_size + 2)^2);

% Frequency vector
freq = zeros(1, steps_number);

% Store real and imaginary components separately
results = struct();

for s = 1:numel(s_names)
    name = s_names{s};

    results.([name '_real']) = zeros(number_layouts, steps_number);
    results.([name '_imag']) = zeros(number_layouts, steps_number);
end

%% 3. Initialize intermediate text file

fid = fopen(data_file, 'w');

if fid == -1
    error('Unable to create output file: %s', data_file);
end

fprintf(fid, 'LAYOUT_NAME\tMATRIZ\tFREQ');

for s = 1:numel(s_names)
    fprintf(fid, '\t%s(real)\t%s(imag)', ...
        s_names{s}, s_names{s});
end

fprintf(fid, '\r\n');
fclose(fid);

%% 4. Run simulations and extract S-parameters

for n = 1:number_layouts

    % Layout identifier
    number = sprintf('%04d', n);
    layout_name = [cell_name number];

    fprintf('Processing layout %d of %d: %s\n', ...
        n, number_layouts, layout_name);

    % Store original binary geometry
    inputs(n, :) = reshape(array{n}, 1, []);

    %% 4.1 Locate simulation directory

    simulation_folder = fullfile(wrk_name_path, ...
        'simulation', lib_name, layout_name, ...
        'layout', emSetup_MoM);

    %% 4.2 Generate Windows batch file

    fid = fopen(file_bat_name, 'w');

    if fid == -1
        error('Unable to create batch file.');
    end

    fprintf(fid, 'cd /d "%s"\r\n', simulation_folder);
    fprintf(fid, 'set "HPEESOF_DIR=%s"\r\n', ruta_program);
    fprintf(fid, 'set "ADS_LICENSE_FILE=%s"\r\n', ruta_license);
    fprintf(fid, 'set "%s"\r\n', ruta_path);

    fprintf(fid, 'adsMomWrapper -O -3D proj proj\r\n');

    fclose(fid);

    %% 4.3 Execute ADS Momentum simulation

    status = system(['"' file_bat_name '"']);

    if status ~= 0
        error('ADS simulation failed for layout %s.', layout_name);
    end

    %% 4.4 Open simulation results

    proj_cti = fullfile(simulation_folder, 'proj.cti');

    fid = fopen(proj_cti, 'r');

    if fid == -1
        error('Unable to open simulation results: %s', proj_cti);
    end

    %% 4.5 Extract frequency samples

    found = false;

    for line = 1:80
        current_line = fgetl(fid);

        if ~ischar(current_line)
            break;
        end

        if strcmp(strtrim(current_line), 'VAR_LIST_BEGIN')
            found = true;
            break;
        end
    end

    if ~found
        fclose(fid);
        error('Frequency section not found in %s.', proj_cti);
    end

    current_freq = zeros(1, steps_number);

    for k = 1:steps_number
        current_line = fgetl(fid);
        current_freq(k) = sscanf(current_line, '%f', 1);
    end

    if n == 1
        freq = current_freq;
    elseif any(abs(freq - current_freq) > 1e-9)
        fclose(fid);
        error('Frequency mismatch in layout %s.', layout_name);
    end

    %% 4.6 Extract the 16 complex S-parameters

    s_values = complex(zeros(steps_number, 16));

    for s = 1:numel(s_names)

        % Locate the next S-parameter data block
        found = false;

        for line = 1:80
            current_line = fgetl(fid);

            if ~ischar(current_line)
                break;
            end

            if strcmp(strtrim(current_line), 'BEGIN')
                found = true;
                break;
            end
        end

        if ~found
            fclose(fid);
            error('Missing %s data in layout %s.', ...
                s_names{s}, layout_name);
        end

        % Read real and imaginary values at each frequency
        for k = 1:steps_number

            current_line = fgetl(fid);

            % Remove separators from CTI data
            current_line = strrep(current_line, ',', ' ');

            values = sscanf(current_line, '%f');

            if numel(values) ~= 2
                fclose(fid);
                error('Invalid %s data in layout %s.', ...
                    s_names{s}, layout_name);
            end

            s_values(k, s) = complex(values(1), values(2));
        end

        % Store one row per geometry
        name = s_names{s};

        results.([name '_real'])(n, :) = real(s_values(:, s)).';
        results.([name '_imag'])(n, :) = imag(s_values(:, s)).';

    end

    fclose(fid);

    %% 4.7 Write intermediate text results

    fid = fopen(data_file, 'a');

    if fid == -1
        error('Unable to append to %s.', data_file);
    end

    geometry_string = mat2str(array{n});
    geometry_string = strrep(geometry_string, ' ', '');

    for k = 1:steps_number

        fprintf(fid, '%s\t%s\t%.12g', ...
            layout_name, geometry_string, freq(k));

        for s = 1:numel(s_names)
            fprintf(fid, '\t%.12g\t%.12g', ...
                real(s_values(k, s)), imag(s_values(k, s)));
        end

        fprintf(fid, '\r\n');
    end

    fclose(fid);

end

%% 5. Save MATLAB dataset

% Add geometry and frequency variables
results.inputs = inputs;
results.freq = freq;

% Save all 32 S-parameter matrices and the input variables
save('trainingData.mat', '-struct', 'results');

fprintf('\nSimulation and data extraction completed.\n');
fprintf('Total geometries: %d\n', number_layouts);
fprintf('Frequency points: %d\n', steps_number);
fprintf('Dataset saved to trainingData.mat\n');





